#!/usr/bin/env python3
"""Generate the FROZEN V1 V16/H24 typed input boundary; --check is read only."""
from pathlib import Path
import sys
TARGET = Path("Solidity/Roadmap/V16/H24Input.lean")
CONTENT = 'import Solidity.Lowering.P8.DeclarationGraphAdmission\nimport Solidity.Lowering.P8b.P8aInterface\n\n/-! FROZEN V1: additive V16 input boundary for the published H24 producer.\nGenerated by scripts/roadmap-v16-h24-interface.py. Signatures only; no producer,\nadmitted input, graph certificate, lowerer or semantic certificate is constructed.\nThe base P8a dependency currently has no concrete inhabitant. This interface\ncannot be counted as inhabited admission or G48/compiler coverage. -/\nnamespace Solidity.Roadmap.V16.H24Input\nopen Solidity.Lowering.P8\n\n/-- The exact H24 wrapper, retaining BOTH graphs and actual Source refusal. -/\nabbrev Producer (S : P8a.Spec) (reference : P8a.OperationalReference)\n    (origins : P8a.SourceOrigins S) (roots : P8a.RootModel S) :=\n  DeclarationGraphAdmission.Producer S reference origins roots\n\n/-- Existing checked frontend receipt at the SAME wrapped base producer.\nNo second checker, acceptance predicate or fragment restriction is introduced. -/\nabbrev CertifiedInput {S : P8a.Spec} {reference : P8a.OperationalReference}\n    {origins : P8a.SourceOrigins S} {roots : P8a.RootModel S}\n    (producer : Producer S reference origins roots) (input : S.Input) :=\n  Solidity.Lowering.P8b.P8aInterface.CertifiedInput producer.base input\n\n/-- Explicit input obligations for later V16 composition. The producer and\nits checked receipt are premises, not fabricated instances. Graph admission is\nindexed by producer.base, including its exact origin/artifact/location indices. -/\nstructure Request {S : P8a.Spec} {reference : P8a.OperationalReference}\n    {origins : P8a.SourceOrigins S} {roots : P8a.RootModel S}\n    (producer : Producer S reference origins roots) (input : S.Input) where\n  checked : CertifiedInput producer input\n  artifact : Roadmap.Artifact\n\n/-- The unchanged P8b lowering/certificate obligation remains SEPARATE from\nH24. No total emitter, dom/agrees proof or G01 Cert follows from Request. -/\nabbrev LoweringObligation (S : P8a.Spec) (I : Roadmap.IntrinsicSpec) :=\n  Solidity.Lowering.P8b.P8aInterface.ProducerOutput S I\n\nend Solidity.Roadmap.V16.H24Input\n'
if sys.argv[1:] == ["--check"]:
    raise SystemExit(0 if TARGET.is_file() and TARGET.read_text() == CONTENT else 1)
if sys.argv[1:]:
    raise SystemExit("usage: roadmap-v16-h24-interface.py [--check]")
TARGET.parent.mkdir(parents=True,exist_ok=True)
TARGET.write_text(CONTENT)
